use crate::api::client::ApiClient;
use crate::models::{ResultWithDefaultError, TimeEntry};
use crate::utilities;
use chrono::{Datelike, NaiveDate};
use std::collections::BTreeMap;

pub struct BillWeeklyCommand;

impl BillWeeklyCommand {
    pub async fn execute(
        api_client: impl ApiClient,
        since: Option<String>,
        until: Option<String>,
    ) -> ResultWithDefaultError<()> {
        let (since, until) = utilities::normalize_time_entry_list_filters(since, until)?;
        let entries = api_client
            .get_time_entries_filtered_minimal(since, until)
            .await?;
        print!("{}", render(&aggregate_billable_seconds(&entries)));
        Ok(())
    }
}

/// Sum stored duration for stopped, billable entries by their UTC ISO-week Monday.
pub fn aggregate_billable_seconds(entries: &[TimeEntry]) -> BTreeMap<NaiveDate, i64> {
    let mut weeks = BTreeMap::new();
    for entry in entries
        .iter()
        .filter(|entry| entry.billable && !entry.is_running())
    {
        let start_date = entry.start.date_naive();
        let monday = start_date
            - chrono::Duration::days(i64::from(start_date.weekday().num_days_from_monday()));
        *weeks.entry(monday).or_insert(0) += entry.duration;
    }
    weeks
}

pub fn render(weeks: &BTreeMap<NaiveDate, i64>) -> String {
    if weeks.is_empty() {
        return "(no data)\n".to_string();
    }

    let mut output = String::new();
    let mut total = 0;
    for (monday, seconds) in weeks {
        output.push_str(&format!("{}  {seconds}s\n", monday.format("%Y-%m-%d")));
        total += seconds;
    }
    output.push_str(&format!("Total  {total}s\n"));
    output
}

#[cfg(test)]
mod tests {
    use super::*;
    use crate::api::client::MockApiClient;
    use chrono::{DateTime, Utc};

    fn entry(id: i64, start: &str, duration: i64, billable: bool, running: bool) -> TimeEntry {
        let start = DateTime::parse_from_rfc3339(start)
            .unwrap()
            .with_timezone(&Utc);
        TimeEntry {
            id,
            description: String::new(),
            start,
            stop: (!running).then_some(start + chrono::Duration::seconds(duration)),
            duration: if running {
                -start.timestamp()
            } else {
                duration
            },
            billable,
            workspace_id: 1,
            tags: vec![],
            project: None,
            task: None,
            created_with: None,
        }
    }

    #[test]
    fn aggregates_billable_stopped_entries_by_utc_monday() {
        let entries = vec![
            entry(1, "2026-01-04T23:30:00Z", 120, true, false),
            entry(2, "2026-01-05T00:30:00Z", 300, true, false),
            entry(3, "2026-01-06T00:30:00Z", 900, false, false),
            entry(4, "2026-01-06T01:30:00Z", 1800, true, true),
        ];

        let weeks = aggregate_billable_seconds(&entries);
        assert_eq!(weeks.len(), 2);
        assert_eq!(weeks[&NaiveDate::from_ymd_opt(2025, 12, 29).unwrap()], 120);
        assert_eq!(weeks[&NaiveDate::from_ymd_opt(2026, 1, 5).unwrap()], 300);
    }

    #[test]
    fn renders_oldest_first_with_total() {
        let weeks = BTreeMap::from([
            (NaiveDate::from_ymd_opt(2026, 1, 5).unwrap(), 300),
            (NaiveDate::from_ymd_opt(2025, 12, 29).unwrap(), 120),
        ]);
        assert_eq!(
            render(&weeks),
            "2025-12-29  120s\n2026-01-05  300s\nTotal  420s\n"
        );
    }

    #[test]
    fn renders_empty_data() {
        assert_eq!(render(&BTreeMap::new()), "(no data)\n");
    }

    #[tokio::test]
    async fn uses_normalized_date_filters() {
        let mut api_client = MockApiClient::new();
        let (expected_since, expected_until) = utilities::normalize_time_entry_list_filters(
            Some("2026-01-01".to_string()),
            Some("2026-01-31".to_string()),
        )
        .unwrap();
        api_client
            .expect_get_time_entries_filtered_minimal()
            .withf(move |since, until| *since == expected_since && *until == expected_until)
            .returning(|_, _| Ok(vec![]));

        BillWeeklyCommand::execute(
            api_client,
            Some("2026-01-01".to_string()),
            Some("2026-01-31".to_string()),
        )
        .await
        .unwrap();
    }
}

