use crate::api::client::ApiClient;
use crate::models::{ResultWithDefaultError, TimeEntry};
use crate::utilities;
use chrono::{Datelike, NaiveDate};
use std::collections::BTreeMap;

pub struct BillWeeklyCommand;

impl BillWeeklyCommand {
    pub async fn execute(
        api_client: impl ApiClient,
        since: Option<String>,
        until: Option<String>,
    ) -> ResultWithDefaultError<()> {
        let (since, until) = utilities::normalize_time_entry_list_filters(since, until)?;
        let entries = api_client
            .get_time_entries_filtered_minimal(since, until)
            .await?;
        print!("{}", render(&aggregate_billable_seconds(&entries)));
        Ok(())
    }
}

/// Sum stored duration for stopped, billable entries by their UTC ISO-week Monday.
pub fn aggregate_billable_seconds(entries: &[TimeEntry]) -> BTreeMap<NaiveDate, i64> {
    let mut weeks = BTreeMap::new();
    for entry in entries.iter().filter(|entry| entry.billable && !entry.is_running()) {
        let start_date = entry.start.date_naive();
        let monday = start_date
            - chrono::Duration::days(i64::from(start_date.weekday().num_days_from_monday()));
        *weeks.entry(monday).or_insert(0) += entry.duration;
    }
    weeks
}

pub fn render(weeks: &BTreeMap<NaiveDate, i64>) -> String {
    if weeks.is_empty() {
        return "(no data)\n".to_string();
    }

    let mut output = String::new();
    let mut total = 0;
    for (monday, seconds) in weeks {
        output.push_str(&format!("{}  {seconds}s\n", monday.format("%Y-%m-%d")));
        total += seconds;
    }
    output.push_str(&format!("Total  {total}s\n"));
    output
}

